for (const mode of ['settled-rejection', 'unknown-cleanup'] as const) test(
  `public native read cut preserves ${mode} after its original sibling revokes the final fetch`, async t => {
    const host = await fixture('stable'); t.after(host.close)
    const diagnostics: unknown[] = [], events = channel('agent-teams:opencode-v2:read-cut-failed')
    const collect = (value: unknown) => { diagnostics.push(value) }
    events.subscribe(collect); t.after(() => { events.unsubscribe(collect) })
    const firstFailure = new Error('invalid_native_read_response')
    const rejectedFetch = new Error(mode === 'unknown-cleanup'
      ? 'native_read_cleanup_unknown' : 'TEST_PRIVATE_ABORTED_FINAL_LOG')
    let fetches = 0, logReads = 0, sessionReads = 0, rejected = 0
    let finalSignal: AbortSignal | null | undefined
    const transport = {
      check() {},
      fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
        fetches++
        const url = new URL(String(input))
        if (url.pathname.endsWith('/log') && ++logReads === 2) {
          const signal = init?.signal
          assert(signal && !signal.aborted)
          finalSignal = signal
          return new Promise<Response>((_resolve, reject) => {
            signal.addEventListener('abort', () => {
              rejected++
              reject(rejectedFetch)
            }, { once: true })
          })
        }
        if (url.pathname === '/api/session/' + sessionID && ++sessionReads === 2)
          return Promise.reject(firstFailure)
        return fetch(input, init)
      },
    }
    await assert.rejects(readOpenCodeV2NativeCut(transport,
      { endpoint: host.endpoint, directory: host.directory, sessionID, pin: '2.0.21' },
      { nativeInputID, beforeCursor: 0, text: 'TEST input' }),
    (error: unknown) => mode === 'settled-rejection' ? error === firstFailure
      : error instanceof Error && error.message === 'native_read_cleanup_unknown')
    assert.deepEqual({ fetches, logReads, sessionReads, rejected },
      { fetches: 6, logReads: 2, sessionReads: 2, rejected: 1 })
    assert.equal(finalSignal?.aborted, true)
    assert.deepEqual(host.counts(), { logs: 1, pages: 2, requests: 4 })
    assert.equal(diagnostics.length, 1)
    const diagnostic = diagnostics[0] as Record<string, unknown>
    assert.equal(Object.isFrozen(diagnostic), true)
    assert.equal(diagnostic.stage, 'after-session')
    assert.equal(diagnostic.reason, 'invalid_native_read_response')
    assert.equal(diagnostic.finalReason, mode === 'unknown-cleanup' ? 'native_read_cleanup_unknown' : 'invalid_native_read_response')
    assert.equal(diagnostic.aborted, false); assert.equal(diagnostic.deadlineExpired, false)
    assert.equal(JSON.stringify(diagnostics).includes('TEST_PRIVATE'), false)
  }
)

test('public native read cut cancels a late fetch response after revocation', async t => {
  const directory = resolve('TEST/native-cut'), controller = new AbortController()
  let deliver!: (response: Response) => void
  let fetched = 0, lateCancellations = 0, nativeSignal: AbortSignal | null | undefined
  const transport = {
    signal: controller.signal,
    check() {},
    fetch(_input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
      fetched++; nativeSignal = init?.signal
      queueMicrotask(() => controller.abort())
      return new Promise<Response>(resolve => { deliver = resolve })
    },
  }
  await assert.rejects(readOpenCodeV2NativeCut(transport,
    { endpoint: 'http://127.0.0.1:12345', directory, sessionID, pin: '2.0.21' },
    { nativeInputID, beforeCursor: 0, text: 'TEST input' }),
  (error: unknown) => error instanceof Error && error.message === 'native_read_cleanup_unknown')
  assert.equal(fetched, 1)
  assert.equal(nativeSignal?.aborted, true)
  // A hostile injected fetch can still fulfill after the read has failed.
  // Its late, previously unobserved response body must not be left open.
  deliver(new Response(new ReadableStream<Uint8Array>({
    cancel() { lateCancellations++ },
  }), { status: 200, headers: { 'content-type': 'application/json' } }))
  await new Promise<void>(resolve => setImmediate(resolve))
  assert.equal(lateCancellations, 1)

  const host = await fixture('stable'); t.after(host.close)
  const failures: unknown[] = [], events = channel('agent-teams:opencode-v2:read-cut-failed')
  const collect = (value: unknown) => { failures.push(value) }
  events.subscribe(collect); t.after(() => { events.unsubscribe(collect) })
  let logReads = 0, sessionReads = 0, finalCancellations = 0
  let finalSignal: AbortSignal | null | undefined, finishFinal!: (response: Response) => void
  const paired = {
    check() {},
    fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
      const url = new URL(String(input))
      if (url.pathname.endsWith('/log') && ++logReads === 2) {
        finalSignal = init?.signal
        return new Promise<Response>(resolve => { finishFinal = resolve })
      }
      if (url.pathname === '/api/session/' + sessionID && ++sessionReads === 2)
        return Promise.reject(new Error('TEST_PRIVATE_FINAL_SESSION'))
      return fetch(input, init)
    },
  }
  await assert.rejects(readOpenCodeV2NativeCut(paired,
    { endpoint: host.endpoint, directory: host.directory, sessionID, pin: '2.0.21' },
    { nativeInputID, beforeCursor: 0, text: 'TEST input' }),
  (error: unknown) => error instanceof Error && error.message === 'native_read_cleanup_unknown')
  assert.equal(logReads, 2); assert.equal(sessionReads, 2)
  assert.equal(finalSignal?.aborted, true, 'the first failed sibling revokes its original pending pair')
  assert.equal(failures.length, 1)
  const diagnostic = failures[0] as Record<string, unknown>
  assert.equal(Object.isFrozen(diagnostic), true)
  assert.deepEqual(Object.keys(diagnostic).sort(), ['aborted', 'deadlineExpired', 'elapsedMs', 'finalReason', 'reason', 'stage'])
  assert.equal(diagnostic.stage, 'after-session'); assert.equal(diagnostic.reason, 'unknown')
  assert.equal(diagnostic.finalReason, 'native_read_cleanup_unknown')
  assert.equal(diagnostic.aborted, false, 'capture precedes the pair self-abort')
  assert.equal(diagnostic.deadlineExpired, false)
  assert.ok(Number.isSafeInteger(diagnostic.elapsedMs) && Number(diagnostic.elapsedMs) >= 0 && Number(diagnostic.elapsedMs) <= 60_000)
  for (const secret of ['TEST_PRIVATE_FINAL_SESSION', sessionID, host.endpoint, host.directory])
    assert.equal(JSON.stringify(failures).includes(secret), false)
  finishFinal(new Response(new ReadableStream<Uint8Array>({ cancel() { finalCancellations++ } }),
    { status: 200, headers: { 'content-type': 'text/event-stream' } }))
  await new Promise<void>(resolve => setImmediate(resolve))
  assert.equal(finalCancellations, 1, 'late original body is reclaimed without rewriting the failed cut')
})

