import type { OpenCodeInputWindowItem, OpenCodeInputWindowPort } from './input-window-capture.ts'
import type { EventPayload, Limits } from '@agent-teams/provider-session-contracts'
import type { AttachmentPort, PreparedAttachment } from '../provider-session-io/attachments.ts'

/** Private seam for the two actual native dialects; no runtime ownership or native DTOs. */
export type DriverPermission = { requestId: string; tool: string; input: unknown }
export type DriverSnapshot = { facts: readonly EventPayload[]; observations?: readonly OpenCodeInputWindowItem[]; terminal?: 'succeeded' | 'failed' | 'cancelled' | undefined; terminalCode?: 'unsupported'; permissions: readonly DriverPermission[] }
export type DriverTurn = { nativeInputId: string; read: () => Promise<DriverSnapshot>; interrupt: () => Promise<void> }
export type DriverProtocol = {
  pollIntervalMs: number
  dispose: () => Promise<void>
  queue: (operationKey: string, text: string, attachments?: readonly PreparedAttachment[]) => Promise<DriverTurn>
  replyPermission: (requestId: string, decision: 'allow' | 'deny', signal: AbortSignal) => Promise<void>
}
export type DriverSessionConfig = {
  binding: Readonly<{ tenantId: string; projectId: string; sessionId: string; generation: number }>
  nativeSessionId: string; trustedBinding: string; engine: 'opencode-v1' | 'opencode-v2'; compatibility: string
  limits: Limits
  attachments?: AttachmentPort
  attachmentModel?: string
  capture?: OpenCodeInputWindowPort
  probe: (signal: AbortSignal) => Promise<boolean>
  confirmStopped: () => Promise<boolean>
}

/** Await bound for finite native requests; owning transport cancels its IO on failure. */
export async function boundV2Request<T>(work: Promise<T>, ms: number, signal?: AbortSignal): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined, abort: (() => void) | undefined
  try {
    signal?.throwIfAborted()
    if (!Number.isFinite(ms) || ms <= 0) {throw new Error('deadline')}
    return await Promise.race([work, new Promise<never>((_resolve, reject) => {
      abort = () =>{  reject(new Error('deadline')); }
      signal?.addEventListener('abort', abort, { once: true })
      timer = setTimeout(abort, ms)
    })])
  } finally { clearTimeout(timer); if (abort) {signal?.removeEventListener('abort', abort)} }
}

import { OpenCodeDriverSession } from './driver-session.ts'
import { createV2DriverBackend } from './v2-driver-backend.ts'
import { driverCompatibility } from './v2-driver-config.ts'
import type { OpenCodeV2DriverConfig } from './v2-driver-config.ts'

export function createV2DriverSession(config: OpenCodeV2DriverConfig) {
  // TypeScript's boolean contract does not constrain an injected Host callback
  // at runtime. A truthy object/number is neither a valid owner admission nor
  // physical process-stop attestation; do not let the shared Session SPI's
  // truthiness checks elevate those values to success.
  const qualified: OpenCodeV2DriverConfig = {
    ...config,
    probe: async signal => (await config.probe(signal)) === true,
    confirmStopped: async () => (await config.confirmStopped()) === true,
  }
  return new OpenCodeDriverSession({ ...qualified, ...(qualified.attachments ? { attachmentModel: qualified.attachments.model } : {}),
    engine: 'opencode-v2', compatibility: driverCompatibility(config) },
    signal => createV2DriverBackend(qualified, signal))
}

export function deferred<T>() {
  let settle!: (value: T) => void;
  const promise = new Promise<T>((resolve) => { settle = resolve; });
  return { promise, resolve: settle };
}
export async function bounded<T>(promise: Promise<T>, timeoutMs: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([promise, new Promise<never>((_resolve, reject) => {
      timer = setTimeout(() => { reject(new Error('deadline')); }, timeoutMs);
    })]);
  } finally { clearTimeout(timer); }
}
/** Single-consumer, byte-and-count bounded event feed. Never silently drops output. */
export class EventFeed<T> implements AsyncIterable<T> {
  private readonly values: { value: T; bytes: number }[] = [];
  private bytes = 0;
  private ended = false;
  private waiter = deferred<void>();
  private claimed = false;
  private terminal: { value: T } | undefined;
  private readonly maxCount: number;
  private readonly maxBytes: number;
  constructor(maxCount: number, maxBytes: number) { this.maxCount = maxCount; this.maxBytes = maxBytes; }
  push(value: T): boolean {
    const bytes = Buffer.byteLength(JSON.stringify(value));
    if (this.ended || this.values.length >= this.maxCount || this.bytes + bytes > this.maxBytes) {return false;}
    this.values.push({ value, bytes }); this.bytes += bytes;
    this.wake(); return true;
  }
  finishWith(value: T): void {
    if (!this.terminal) {this.terminal = { value };}
    this.end();
  }
  end(): void { this.ended = true; this.wake(); }
  private wake(): void { this.waiter.resolve(); this.waiter = deferred<void>(); }
  async *[Symbol.asyncIterator](): AsyncGenerator<T> {
    if (this.claimed) {throw new Error('single observer required');}
    this.claimed = true;
    for (;;) {
      const next = this.values.shift();
      if (next) { this.bytes -= next.bytes; yield next.value; }
      else if (this.ended) {
        if (this.terminal) { const terminal = this.terminal; this.terminal = undefined; yield terminal.value; }
        return;
      }
      else {await this.waiter.promise;}
    }
  }
}

import type { V2ExecutionVersion } from './v2-protocol-version.ts'
export class ExecutionTransportFailure extends Error {
  readonly code: string
  readonly disposition: 'not_submitted' | 'unknown'
  constructor(code: string, disposition: 'not_submitted' | 'unknown') { super(code); this.code = code; this.disposition = disposition }
}
export const unsubmitted = new WeakSet<object>()
export type V2SessionAbsenceBinding = { sessionId: string; endpoint: string; directory: string; version: V2ExecutionVersion }
export const missingSessions = new WeakMap<object, V2SessionAbsenceBinding>()
export function executionSessionIsMissing(error: unknown, expected: V2SessionAbsenceBinding): boolean {
  if (error === null || typeof error !== 'object') {return false}
  const wrapped = error as { name?: unknown; reason?: unknown; cause?: unknown }
  const binding = missingSessions.get(error) ?? (wrapped.name === 'ClientError' && wrapped.reason === 'Transport'
    && wrapped.cause !== null && typeof wrapped.cause === 'object' ? missingSessions.get(wrapped.cause) : undefined)
  return binding !== undefined && binding.sessionId === expected.sessionId && binding.endpoint === expected.endpoint
    && binding.directory === expected.directory && binding.version === expected.version
}
export function executionWasNotSubmitted(error: unknown): boolean {
  if (error === null || typeof error !== 'object') {return false}
  if (unsubmitted.has(error)) {return true}
  // Both exact Promise clients wrap a fetch rejection in ClientError(Transport)
  // with its original cause. Trust only the privately minted cause identity.
  const wrapped = error as { name?: unknown; reason?: unknown; cause?: unknown }
  return wrapped.name === 'ClientError' && wrapped.reason === 'Transport' &&
    wrapped.cause !== null && typeof wrapped.cause === 'object' && unsubmitted.has(wrapped.cause)
}
export function executionAssert(value: boolean, code = 'invalid_response'): asserts value {
  if (!value) {throw new ExecutionTransportFailure(code, 'not_submitted')}
}
